    void emptyItemListCostsOnlyTheProcessingFee() {
        int exitCode = run("""
                {"customer": {"yearsWithMHPCO": 0},
                 "steps": [{"op": "quote", "items": []}]}""");

        assertEquals(0, exitCode);
        assertEquals("{\\"results\\":[{\\"premium\\":5}]}", stdout().trim());
    }''')
open(p,'w').write(s)
