import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.List;

public final class ClaimOfficeCli {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ClaimOfficeCli() {
    }

    public static int run(InputStream in, PrintStream out, PrintStream err) {
        JsonNode scenario;
        try {
            scenario = MAPPER.readTree(in);
        } catch (IOException e) {
            err.println(e.getMessage());
            return 1;
        }
        List<Item> items = itemsOf(scenario.get("steps").get(0));
        int premium = PremiumCalculator.premiumFor(items);
        out.print("{\"results\":[{\"premium\":" + premium + "}]}");
        return 0;
    }

    private static List<Item> itemsOf(JsonNode quoteStep) {
        List<Item> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new Item(item.get("type").asText()));
        }
        return items;
    }

    public static void main(String[] args) {
        System.exit(run(System.in, System.out, System.err));
    }
}
