 * of alike components will be recognised. Knows nothing about the surcharges,
 * discounts and the processing fee that turn a base premium into a premium.
 */
final class PolicyBasePremium {

    private PolicyBasePremium() {
    }

    static int of(List<Item> items) {
        return items.stream().mapToInt(PriceList::basePremiumFor).sum();
    }
}
