import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * The base premium the MHPCO tariffs a whole quote at.
 *
 * <p>Knows how the items of a quote are tariffed together: the sum of the
 * individual base premiums, except that alike components form a building block
 * offered at a special base premium. Knows nothing about the surcharges,
 * discounts and the processing fee that turn a base premium into a premium.
 */
final class PolicyBasePremium {

    private static final int BLOCK_SIZE = 3;
    private static final int BLOCK_BASE_PREMIUM_IN_G = 60;

    private PolicyBasePremium() {
    }

    static int of(List<Item> items) {
        Map<String, List<Item>> alike = items.stream()
                .collect(Collectors.groupingBy(Item::type));
        return alike.values().stream().mapToInt(PolicyBasePremium::basePremiumForAlike).sum();
    }

    private static int basePremiumForAlike(List<Item> alike) {
        if (alike.size() == BLOCK_SIZE) {
            return BLOCK_BASE_PREMIUM_IN_G;
        }
        return alike.stream().mapToInt(PriceList::basePremiumFor).sum();
    }
}
EOF
