import java.util.List;

/**
 * Which insured item a damage entry of an incident names.
 *
 * <p>A damage entry names its item by type, the way the report is written;
 * what the clauses need is the insured item itself, with its enchantment and
 * its material. This is the one place that reads a report's item type against
 * the items a policy covers.
 *
 * <p>Changes whenever the MHPCO revises how a report is read against a policy
 * — notably once a policy may cover several items of the same type and each
 * entry must be matched to one of them. Knows nothing about what is
 * reimbursed for the item it finds.
 */
final class DamagedItem {

    private DamagedItem() {
    }

    /**
     * The insured item a damage entry names.
     */
    static Item of(List<Item> insured, Damage damage) {
        return insured.stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst()
                .orElseThrow();
    }
}
import java.math.BigDecimal;
import java.util.List;

/**
 * What the MHPCO reimburses for an incident, before the policy's cap is
 * applied.
 *
 * <p>Knows that a deductible applies per damage event — once for each damaged
 * item — and that it is taken off after the clauses have said how much of the
 * damage is reimbursed at all. Defers which item a damage entry names, and
 * what the clauses make of it, to those two.
 */
final class Reimbursement {

    private static final BigDecimal DEDUCTIBLE_IN_G = BigDecimal.valueOf(100);

    private Reimbursement() {
    }

    static BigDecimal of(List<Item> items, Incident incident) {
        return incident.damages().stream()
                .map(damage -> reimbursementFor(items, damage))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static BigDecimal reimbursementFor(List<Item> insured, Damage damage) {
        Item damaged = DamagedItem.of(insured, damage);
        return DamageClause.reimbursedPartOf(damaged, BigDecimal.valueOf(damage.amount()))
                .subtract(DEDUCTIBLE_IN_G)
                .max(BigDecimal.ZERO);
    }
}
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;

public final class ClaimOfficeCli {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ClaimOfficeCli() {
    }

    public static int run(InputStream in, PrintStream out, PrintStream err) {
        JsonNode scenario;
        try {
            scenario = MAPPER.readTree(in);
        } catch (IOException e) {
            err.println(e.getMessage());
            return 1;
        }
        out.print(ScenarioJson.results(ScenarioJson.scenarioOf(scenario).settle()));
        return 0;
    }

    public static void main(String[] args) {
        System.exit(run(System.in, System.out, System.err));
    }
}

