cat > src/main/java/DamagedItem.java <<'EOF'
import java.util.ArrayList;
import java.util.List;

/**
 * Which insured item each damage entry of an incident names.
 *
 * <p>A damage entry names its item by type, the way the report is written;
 * what the clauses need is the insured item itself, with its enchantment and
 * its material. A policy may cover several items of the same type, so each
 * entry is matched to a separate insured item: the MHPCO will not settle the
 * same item twice on one report, and a report naming more items of a type than
 * the policy covers is refused outright.
 *
 * <p>Changes whenever the MHPCO revises how a report is read against a policy;
 * knows nothing about what is reimbursed for the items it finds.
 */
final class DamagedItem {

    private DamagedItem() {
    }

    /**
     * The insured items the damage entries name, in the order they are
     * reported.
     */
    static List<Item> of(List<Item> insured, List<Damage> damages) {
        List<Item> unclaimed = new ArrayList<>(insured);
        List<Item> damaged = new ArrayList<>();
        for (Damage damage : damages) {
            damaged.add(claim(unclaimed, damage));
        }
        return damaged;
    }

    private static Item claim(List<Item> unclaimed, Damage damage) {
        for (int index = 0; index < unclaimed.size(); index++) {
            if (unclaimed.get(index).type().equals(damage.itemType())) {
                return unclaimed.remove(index);
            }
        }
        throw new RejectedScenario(
                "the policy does not cover a " + damage.itemType() + " for this damage");
    }
}
